package net.minecraft.util;public class Vec3{public double xCoord,yCoord,zCoord;public Vec3(double x,double y,double z){xCoord=x;yCoord=y;zCoord=z;}public static Vec3 createVectorHelper(double x,double y,double z){return new Vec3(x,y,z);}public double distanceTo(Vec3 b){return Math.sqrt(Math.pow(xCoord-b.xCoord,2)+Math.pow(yCoord-b.yCoord,2)+Math.pow(zCoord-b.zCoord,2));}}
